SELECT import_new_structured_page_v1('3cbdc749-e9c9-44f3-8330-ecc1e3b38cc8'::uuid, '59d7f112-fb58-4726-9c35-11485c6155e7'::uuid, 'a2000000-0000-4000-8000-000000000001'::uuid, 'a3000000-0000-4000-8000-000000000001'::uuid, 'a4000000-0000-4000-8000-000000000005'::uuid, '{"pageId": "e0600000-0000-4000-8000-000000000001", "bookPartId": "59d7f112-fb58-4726-9c35-11485c6155e7", "pageNumber": 60, "sourceShowsPrintedPageLabel": true, "printedPageLabel": "60", "printedPageNumber": 60, "pdfPageNumber": 443, "sequenceIndex": 50, "verificationStatus": "in_review", "scanLanguages": ["en"], "reviewEvidence": {"englishTranscriptionComplete": true, "arabicTranscriptionComplete": false, "blockOrderChecked": true, "identifiersChecked": true, "scanCompared": true}, "structuralNodes": [], "blocks": [{"id": "f0600000-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 0, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "Virtues of Salaat", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 60"}, {"id": "f0600100-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 1, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "get it established universally by propagating it and by arranging special congregations, where it can be performed with absolute uniformity of form and purpose.\"\n\n\"Further, in every community or religious society, there are a few who have the capacity to lead, while the rest simply follow. There are some others who can be corrected with a little counsel or reproach. Then there is a third grade of people who are very weak in faith and, if they are not made to worship in public, they are prone to discard it altogether. It is therefore in the best interests of the Islamic society that all its members perform the worship collectively and in congregation, so that the delinquents may be distinguished from the observers and the shirkers from the adherents. This will also cause the people with less knowledge to follow the Ulama, and make the ignorant to learn from the learned the specific requirements of worship. The worshipper will distinguish right from wrong and genuine from counterfeit, so that the right and the genuine may prevail and the wrong and the counterfeit may be suppressed.\"\n\n\"Besides, these congregations of people loving Allah, seeking His Mercy, constantly fearing Him and having their hearts and souls turned to Him alone, have the wonderful effect of causing His blessings and Mercy to descend from Heaven.\n\n\"Moreover, the Muslim community has been raised so that the word of Allah be held supreme and Islamic Order be paramount over all others. This object cannot be achieved unless all Muslims, big and small, the elite and the common, the town folk and the countrymen, perform alike the most sublime service and the most sacred ritual of Islam (i.e., salaat) by assembling together in one place. It is for this reason that the Sharee-at (Islamic Law) lays such special stress on Friday congregation and on salaat with jamaat, by explaining the blessings that accrue therefrom and punishments awarded for neglect thereof. For the open and conspicuous observance of this important service, two types of assemblies are required; one for people of a clan or a particular locality and the other for the people of the whole town. Since the assembly of the former at any hour is convenient and that of the latter comparatively difficult, so for the former the gathering for salaat (with jamaat) five times daily, has been laid down and in the case of the latter gathering, the weekly Friday salaat has been devised and ordained.\"", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 60"}]}'::jsonb);